/**
 * AIVORA AI News – real article headlines (not generated by Gemini).
 * Free public Google News RSS with a Hacker News Algolia fallback.
 * GET /api/ai-news  => { articles:[{title,url,source,publishedAt}], provider, fetchedAt }
 * No keys, no student data, no fictitious articles.
 */

const AI_PATTERN=/\b(?:AI|A\.I\.|artificial intelligence|machine learning|deep learning|generative ai|genai|llm|llms|large language models?|foundation models?|OpenAI|ChatGPT|Anthropic|Claude|Gemini|DeepMind|Grok|xAI|Mistral|Llama|GPT(?:-\d|\b)|Copilot|Perplexity|AI agents?|AI chips?|neural networks?|transformer models?|diffusion models?)\b/i;
const MAX_AGE_MS=14*24*60*60*1000;
function decodeEntities(s){return String(s||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1')
 .replace(/&#(x[0-9a-f]+|\d+);/gi,(_,n)=>{let c=n[0].toLowerCase()==='x'?parseInt(n.slice(1),16):parseInt(n,10);return Number.isInteger(c)&&c>0&&c<=0x10ffff?String.fromCodePoint(c):''})
 .replace(/&(?:amp|lt|gt|quot|apos|nbsp);/g,c=>({'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&apos;':"'",'&nbsp;':' '}[c]));}
function xmlValue(fragment,name){const m=fragment.match(new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${name}>`,'i'));return m?decodeEntities(m[1]).trim():'';}
function sourceFromXml(item){const m=item.match(/<source(?:\s[^>]*)?>([\s\S]*?)<\/source>/i);return m?decodeEntities(m[1]).trim():'';}
function secureLink(raw){try{const u=new URL(raw);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return ''}}
function eligible(item){if(!AI_PATTERN.test(item.title))return false;const when=Date.parse(item.publishedAt);return Number.isFinite(when)&&when<=Date.now()+3600000&&when>=Date.now()-MAX_AGE_MS}
function parseGoogle(xml){
 const entries=xml.match(/<item(?:\s[^>]*)?>[\s\S]*?<\/item>/gi)||[];
 return entries.map(item=>{
  const original=xmlValue(item,'title');const source=sourceFromXml(item)||'Google News';
  const suffix=' - '+source;
  const title=original.endsWith(suffix)?original.slice(0,-suffix.length):original;
  return{title,url:secureLink(xmlValue(item,'link')),source,publishedAt:xmlValue(item,'pubDate')};
 }).filter(x=>x.title&&x.url&&x.publishedAt&&eligible(x));
}
function parseHN(body){return (body?.hits||[]).map(h=>({title:typeof h.title==='string'?h.title:'',url:secureLink(h.url)||secureLink(h.objectID?`https://news.ycombinator.com/item?id=${h.objectID}`:''),source:'Hacker News',publishedAt:h.created_at})).filter(x=>x.title&&x.url&&eligible(x));}
async function getText(url,ms=6800){const c=new AbortController(),timer=setTimeout(()=>c.abort(),ms);try{const r=await fetch(url,{signal:c.signal,headers:{'User-Agent':'AivoraAI-NewsFeed/1.0 (+https://aivora-works.vercel.app)','Accept':'application/rss+xml, application/xml, text/xml, */*'}});if(!r.ok)throw Error('Feed HTTP '+r.status);return await r.text()}finally{clearTimeout(timer)}}
async function getJSON(url,ms=6800){const c=new AbortController(),timer=setTimeout(()=>c.abort(),ms);try{const r=await fetch(url,{signal:c.signal,headers:{Accept:'application/json'}});if(!r.ok)throw Error('Feed HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}}
const feeds=[
 'https://news.google.com/rss/search?q='+encodeURIComponent('(AI OR "artificial intelligence" OR OpenAI OR ChatGPT OR Gemini OR Anthropic OR "machine learning") when:7d')+'&hl=en-US&gl=US&ceid=US:en',
 'https://hn.algolia.com/api/v1/search_by_date?query='+encodeURIComponent('AI')+'&tags=story&hitsPerPage=70'
];
let memo={at:0,articles:[],provider:''};
export async function GET(){
 if(memo.articles.length&&Date.now()-memo.at<5*60*1000)
  return Response.json({articles:memo.articles,provider:memo.provider,fetchedAt:new Date(memo.at).toISOString()}, {headers:{'Cache-Control':'public, s-maxage=300, stale-while-revalidate=600','X-Content-Type-Options':'nosniff'}});
 const [google,hn]=await Promise.allSettled([getText(feeds[0]),getJSON(feeds[1])]);
 let primary=[],secondary=[];
 try{if(google.status==='fulfilled')primary=parseGoogle(google.value)}catch(e){console.warn('AI News RSS parse error',e?.message)}
 try{if(hn.status==='fulfilled')secondary=parseHN(hn.value)}catch(e){console.warn('AI News HN parse error',e?.message)}
 // Prefer verified-source news; Hacker News adds selected developer/AI coverage.
 const seen=new Set();const articles=[...primary,...secondary].filter(x=>{const key=x.title.toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,100);if(!key||seen.has(key))return false;seen.add(key);return true;})
 .sort((a,b)=>Date.parse(b.publishedAt)-Date.parse(a.publishedAt)).slice(0,24);
 if(!articles.length){
  console.warn('AI News feed unavailable:',google.status==='rejected'?google.reason?.message:'RSS returned no AI stories',hn.status==='rejected'?hn.reason?.message:'HN returned no AI stories');
  return Response.json({articles:[],provider:'News sources',error:'News is temporarily unavailable. Try again later.'},{status:503,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})
 }
 const provider=primary.length?'Google News & Hacker News':'Hacker News';memo={at:Date.now(),articles,provider};
 return Response.json({articles,provider,fetchedAt:new Date(memo.at).toISOString()}, {headers:{'Cache-Control':'public, s-maxage=300, stale-while-revalidate=600','X-Content-Type-Options':'nosniff'}})
}
